    home: { titleLead: "Je construis des produits numériques – ", titleEmphasis: "du web et du mobile au développement assisté par l'IA.", intro: "Plus de 11 ans entre web, mobile et management d'ingénierie : 100+ projets web, des plateformes Flutter en production, plusieurs équipes en parallèle et l'IA utilisée comme un vrai outil d'ingénierie, pas comme un argument marketing.", proof: [{ value: "11+", label: "ans d'ingénierie logicielle" }, { value: "100+", label: "produits web livrés" }, { value: "3", label: "équipes produit en parallèle" }, { value: "15", label: "ingénieurs encadrés" }, { value: "3", label: "packages runtime publics" }], mandateLabel: "Ingénierie de bout en bout", mandateTitle: "L'étendue du web. La profondeur du mobile. L'IA dans la pratique.", mandateBody: "Denis a commencé par livrer des sites, des boutiques en ligne, des outils d'administration, des calculateurs, des paiements et des systèmes de génération de leads. Il est ensuite passé aux plateformes mobiles et au management de plusieurs équipes. Aujourd'hui, l'IA fait partie du cycle d'ingénierie – de la recherche et du prototypage à l'implémentation, aux tests et à la documentation –, mais la responsabilité du résultat reste humaine.", capabilityLabel: "Trois forces qui se complètent", capabilityTitle: "Un seul ingénieur, de l'interface jusqu'à la production.", capabilities: [
      { code: "WEB", title: "Web product engineering", body: "Architecture frontend et produit, e-commerce, interfaces opérationnelles, intégrations, performance, accessibilité et les systèmes de livraison qui les entourent.", evidence: "100+ projets web · fondateur de studio · AngularDart · stack React/Vinext actuelle" },
      { code: "MOB", title: "Plateformes mobiles et management", body: "Architecture Flutter, frontières Kotlin/Swift, CI/CD, stores, observabilité, gouvernance des releases et management de plusieurs équipes.", evidence: "11+ ans au total · 6+ ans de Flutter · 3 équipes · 80+ releases" },
      { code: "AI", title: "Ingénierie assistée par l'IA", body: "L'IA au service de la recherche structurée, de l'exploration de solutions, du prototypage produit, de l'implémentation, de la revue de code, de la conception des tests et de la documentation technique – jamais de la production non vérifiée.", evidence: "Workflows agentiques · tranches de produit rapides · vérification avant livraison" },
    ], careerTitle: "Du web aux plateformes mobiles – et maintenant à l'ingénierie avec l'IA.", careerIntro: "Une progression cumulative : l'étendue des produits web, la profondeur des systèmes mobiles, le management d'ingénierie et une pratique moderne assistée par l'IA, qui accélère sans diluer la responsabilité." },
    work: { title: "Produits web, plateformes mobiles et systèmes de mise en production.", intro: "Une sélection de programmes où Denis portait la responsabilité de la livraison, de la qualité de la plateforme ou d'une frontière technique difficile. Le portfolio commence par le web product engineering, puis s'étend à l'architecture mobile et à la responsabilité de plusieurs équipes.", webCase: { label: "05 · Web product engineering", title: "Plus de 100 produits web avant le chapitre mobile", summary: "Cinq ans de fondations : sites, e-commerce, panneaux d'administration, calculateurs, intégrations de paiement et systèmes de génération de leads.", context: "Les PME avaient besoin de produits numériques complets, pas d'un travail d'interface isolé : cadrage, implémentation, hébergement, intégrations et un chemin vers un usage mesurable.", responsibility: "A fondé et dirigé un studio web de deux à quatre personnes, en restant hands-on sur le frontend, la logique produit, les intégrations, la livraison et la relation client.", approach: "A construit des solutions proportionnées pour le commerce, l'administration, les paiements, les calculs et la génération de leads, en choisissant à chaque fois l'architecture la plus simple qui puisse être exploitée après la livraison.", outcome: "Plus de 100 projets web de petite et moyenne taille livrés entre 2015 et 2019 – le socle du travail produit, plateforme et management qui a suivi.", stack: "HTML/CSS, JavaScript, PHP, CMS et plateformes e-commerce, intégrations de paiement, analytics, hébergement, AngularDart" } },
    services: { title: "Product engineering senior pour le web, le mobile et l'IA.", intro: "Faites appel à Denis quand un produit numérique a besoin d'un responsable crédible sur l'interface, l'architecture, la livraison, la production et les workflows IA modernes capables d'accélérer chaque étape.", additions: [
      { title: "Web product engineering et modernisation", signal: "Un produit web doit passer de l'idée à la production, ou un frontend existant est devenu lent, fragile ou difficile à faire évoluer.", action: "Clarifie les parcours produit, redéfinit les frontières du frontend et des intégrations, améliore l'accessibilité et la performance, et met en place un chemin de livraison maintenable.", format: "Construction produit ciblée, sprint de modernisation, revue d'architecture ou direction technique hands-on." },
      { title: "Workflows IA appliqués et prototypage produit", signal: "Une équipe veut un vrai levier grâce à l'IA, mais a besoin de plus que des démos, des collections de prompts ou du code généré sans relecture.", action: "Conçoit un workflow où la vérification passe en premier – recherche, prototypage, implémentation, tests, documentation et revue – et le prouve sur une tranche de produit proche de la production.", format: "Évaluation du workflow, sprint d'accompagnement, prototype produit rapide ou intégration dans un système d'ingénierie existant." },
    ] },
    about: { title: "Product engineer avant d'être spécialiste d'un framework.", intro: "Denis est Engineering Manager et ingénieur hands-on, avec plus de 11 ans d'expérience en produits web, plateformes mobiles, runtimes open source et développement assisté par l'IA.", paragraphs: ["Le parcours commence dans le web : un petit studio, plus de 100 projets livrés, du e-commerce, des systèmes d'administration, des paiements, des calculateurs et des parcours de génération de leads. Cette étendue a forgé un regard produit bien avant la banque, les marketplaces, la fintech et Flutter.", "Le mobile a apporté des contraintes de plateforme plus dures : l'intégration Kotlin et Swift, la signature des apps, les stores, la CI/CD, l'observabilité, les incidents en production et une architecture partagée entre plusieurs applications. Le management a ensuite étendu cette responsabilité aux Team Leads, aux roadmaps, au recrutement et à trois équipes en parallèle.", "L'IA fait désormais partie de la méthode de travail. Denis s'en sert pour condenser la recherche, explorer des architectures, prototyper des interfaces, écrire et relire du code, concevoir des tests et produire de la documentation. L'exigence reste la même : des preuves, des arbitrages explicites et un humain responsable de ce qui part en production."] },
    contact: { title: "Venez avec le vrai problème.", intro: "Un produit web sans chemin vers la production, une release mobile qui ne se stabilise pas, une équipe aux responsabilités floues ou un workflow IA qui doit devenir de l'ingénierie fiable." },
